from typing import List

def minimumCost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    # Distance matrix for all pairs of lowercase English letters (26x26)
    # Initialize with infinity, and 0 on the diagonal.
    dist = [[float('inf')] * 26 for _ in range(26)]
    for i in range(26):
        dist[i][i] = 0

    # Fill initial costs from given mappings
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - ord('a')
        v = ord(c) - ord('a')
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    # Calculate total cost for the transformation
    for s, t in zip(source, target):
        u = ord(s) - ord('a')
        v = ord(t) - ord('a')
        d = dist[u][v]
        if d == float('inf'):
            return -1
        total_cost += d

    return int(total_cost)

