    for length in range(n, 0, -1):
        # 檢查所有可能的子字串
        for i in range(n - length + 1):
            sub = s[i : i + length]

            # 判斷是否為 special string (只有一種字元)
            if len(set(sub)) == 1:
                count = 0
                # 計算該子字串在 s 中出現的次數（包含重疊）
                for j in range(n - length + 1):
                    if s[j : j + length] == sub:
                        count += 1

                # 如果出現次數至少為 3，回傳當前長度
                if count >= 3:
                    return length

    return -1
